using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the first and last name of the current user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetNameAsync(string firstName = default, string lastName = default)
    {

           using var activity =  StartCallActivity("SetNameAsync", typeof(SetName).FullName ?? "SetNameAsync");

           try
           {
             return client.SetNameAsync(firstName, lastName);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
